// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        uint256 bal = address(c).balance;
        assertTrue(ok == false || bal == 0);
        try c.withdrawAll() {
            assertTrue(address(c).balance == 0);
        } catch {
            assertTrue(address(c).balance == 1 ether);
        }
    }
}
